<?php
namespace App\Http\Controllers;use App\Http\Controllers\Controller;use App\Models\CommunicationDelivery;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CommunicationWebhookController extends Controller{public function delivery(Request $r,string $channel){$secret=config("services.$channel.webhook_secret");abort_unless($secret&&hash_equals($secret,(string)$r->header('X-Webhook-Secret')),401);$d=$r->validate(['message_id'=>'required|string','status'=>'required|string','response'=>'nullable']);$delivery=CommunicationDelivery::where('provider_message_id',$d['message_id'])->firstOrFail();$status=in_array(strtolower($d['status']),['delivered','success'])?'delivered':(in_array(strtolower($d['status']),['failed','rejected','undelivered'])?'failed':'sent');$delivery->update(['status'=>$status,'provider_response'=>is_string($d['response']??null)?$d['response']:json_encode($d['response']??null),'delivered_at'=>$status==='delivered'?now():null,'failed_at'=>$status==='failed'?now():null]);$c=$delivery->campaign;$pending=$c->deliveries()->whereIn('status',['queued','retrying','sent'])->exists();if(!$pending)$c->update(['status'=>'completed','completed_at'=>now(),'sent_count'=>$c->deliveries()->whereIn('status',['sent','delivered','simulated'])->count(),'failed_count'=>$c->deliveries()->where('status','failed')->count()]);return response()->json(['received'=>true]);}}
